$r=$m->migrate($u);$check('idempotent_resume',$r['state']==='already_migrated'&&(int)$db->one('SELECT COUNT(*) AS n FROM '.$db->table('event').' WHERE user_id=? AND kind=?',array($u,'opening'))['n']===1);
$check('legacy_claims_preserved',(int)$db->one('SELECT COUNT(*) AS n FROM '.$db->table('event').' WHERE user_id=? AND kind=?',array($u,'legacy_claim'))['n']===2);
$bad=$fixture('mismatch',200,150);$r=$m->migrate($bad);$check('mismatch_reconciliation',$r['state']==='needs_review'&&get_user_meta($bad,'rewardly_loyalty_points_balance',true)==='200');try{$wallet->apply($bad,$run.':blocked','credit',1);$check('unready_blocks_writes',false);}catch(Nodevora_Financial_Error $e){$check('unready_blocks_writes',true);}
