class Nodevora_Migration_Write_Fault extends Nodevora_Financial_DB{private $writes=0;public function query($sql,$params=array()){if(preg_match('/^(INSERT|UPDATE)/',$sql)&&++$this->writes===4){throw new Nodevora_Financial_Error('Injected migration interruption.');}return parent::query($sql,$params);}}
